"""Convert Keras ``weights.weights.h5`` files from IGM into PyTorch tensors.

Keras stores convolution kernels as ``(kh, kw, in, out)`` and works in NHWC;
PyTorch wants ``(out, in, kh, kw)`` and NCHW. The transpose below is the only
difference -- no values are rescaled.

Two on-disk variants exist in the wild and both are handled:

* files whose ``vars`` groups carry a ``name`` attribute (authoritative);
* files re-saved by a later Keras where some layers fell back to autogenerated
  ``conv2d``/``conv2d_N`` names. Those are recovered from creation order,
  and every recovered layer is checked against the shape the model expects, so
  a wrong guess cannot pass silently.
"""

from pathlib import Path
from typing import Dict, List

import h5py
import numpy as np
import torch


def _collect_h5(path: Path):
    """Return ``(named, ordered)``: name -> vars, and the raw h5-path -> vars map."""
    named: Dict[str, List[np.ndarray]] = {}
    ordered: Dict[str, List[np.ndarray]] = {}

    with h5py.File(path, "r") as f:
        def visit(group, prefix=""):
            for key in group:
                item = group[key]
                if not isinstance(item, h5py.Group):
                    continue
                var = item.get("vars")
                if isinstance(var, h5py.Group) and len(var.keys()) > 0:
                    arrays = [var[str(i)][()] for i in range(len(var.keys()))]
                    if len(arrays) == 2:  # conv layer: kernel + bias
                        ordered[f"{prefix}/{key}"] = arrays
                        name = var.attrs.get("name")
                        if name:
                            named[str(name)] = arrays
                visit(item, f"{prefix}/{key}")

        visit(f)

    return named, ordered


def _layer_order(model) -> List[str]:
    """Layer names in Keras construction order, which fixes the autogenerated names."""
    names = ["context_in"]
    for i in range(len(model.context_blocks)):
        names += [f"context_block_{i}_conv1", f"context_block_{i}_conv2"]
    names += ["slide_head_conv1", "slide_head_conv2", "slide_head_out"]
    names += ["def_head_conv1", "def_head_conv2", "def_head_out"]
    names += ["res_head_conv1", "res_head_conv2", "res_head_out"]
    return names


def _torch_modules(model) -> Dict[str, torch.nn.Module]:
    mods = {"context_in": model.context_in}
    for i, block in enumerate(model.context_blocks):
        mods[f"context_block_{i}_conv1"] = block["conv1"]
        mods[f"context_block_{i}_conv2"] = block["conv2"]
    for head in ("slide", "def", "res"):
        for part in ("conv1", "conv2", "out"):
            mods[f"{head}_head_{part}"] = getattr(model, f"{head}_head_{part}")
    return mods


def load_keras_weights_into(model, weights_path) -> None:
    """Load a Keras SIADecompNet checkpoint into the PyTorch ``model`` in place."""
    weights_path = Path(weights_path)
    if weights_path.is_dir():
        weights_path = weights_path / "export" / "weights.weights.h5"
    if not weights_path.exists():
        raise FileNotFoundError(f"Missing emulator weights at {weights_path}")

    named, ordered = _collect_h5(weights_path)
    modules = _torch_modules(model)

    if not set(modules).issubset(named):
        # Recover the layers that lost their name attribute. Keras numbers
        # autogenerated names by construction order; explicitly named layers
        # never enter that sequence.
        auto_keys = sorted(
            (k for k in ordered if k.rsplit("/", 1)[-1].startswith("conv2d")),
            key=lambda k: int(k.rsplit("_", 1)[-1]) if k.rsplit("_", 1)[-1].isdigit() else 0,
        )
        unnamed = [n for n in _layer_order(model) if n not in named]
        if len(unnamed) != len(auto_keys):
            raise ValueError(
                f"Cannot map {weights_path}: {len(unnamed)} layers lack a stored name "
                f"but {len(auto_keys)} autogenerated groups were found."
            )
        for name, key in zip(unnamed, auto_keys):
            named[name] = ordered[key]

    missing = sorted(set(modules) - set(named))
    if missing:
        raise ValueError(f"No source weights found for layers: {missing}")

    for name, module in modules.items():
        kernel, bias = (np.asarray(a, dtype=np.float32) for a in named[name])
        # Keras (kh, kw, in, out) -> torch (out, in, kh, kw)
        kernel_t = torch.from_numpy(np.transpose(kernel, (3, 2, 0, 1)).copy())
        bias_t = torch.from_numpy(bias.copy())
        if kernel_t.shape != module.weight.shape:
            raise ValueError(
                f"Kernel shape mismatch for {name}: file gives {tuple(kernel_t.shape)}, "
                f"model expects {tuple(module.weight.shape)}"
            )
        if bias_t.shape != module.bias.shape:
            raise ValueError(
                f"Bias shape mismatch for {name}: file gives {tuple(bias_t.shape)}, "
                f"model expects {tuple(module.bias.shape)}"
            )
        with torch.no_grad():
            module.weight.copy_(kernel_t)
            module.bias.copy_(bias_t)
